<script setup>
import {computed,ref,reactive,watch} from 'vue';
import {activeTab,apiFetch,setActivePanelTab} from './store.js';
import MilestoneOptions from './MilestoneOptions.vue';
import {resolveMilestone} from './milestones.mjs';
import Icon from './HelmLabIcon.vue';
import ReleaseTrackers from './ReleaseTrackers.vue';
import TrackerWorkQueue from './TrackerWorkQueue.vue';
import {trackerLibrary,selectedTracker,changeTracker,trackerBusy} from './release-trackers-store.mjs';
import {ownsSavedWork,matchingWorkMilestone} from './release-trackers.mjs';
import {myWorkSnapshot as snapshot,myWorkLoading as loading,myWorkRefreshing as refreshing,myWorkError as error,refreshMyWork,pullMyWork} from './my-work-store.mjs';
const form=reactive({repo:'rancher/rancher',milestone:0,scope:'mine',user:'',label:''}),milestones=ref([]),lookupBusy=ref(false),lookupError=ref(''),filter=ref('open'),query=ref(''),notice=ref('');
const milestoneText=ref(''),scopeOpen=ref(false),showMilestones=ref(false),attachTarget=ref('');
const intakeMilestone=computed(()=>resolveMilestone([...milestones.value,...(snapshot.value?.config.repo===form.repo?[snapshot.value.milestone]:[])],milestoneText.value));
const tracked=computed(()=>trackerLibrary.value.trackers.filter(t=>!t.archived));
const unlinked=computed(()=>snapshot.value&&!tracked.value.some(t=>ownsSavedWork(t,snapshot.value)));
const candidates=computed(()=>[...tracked.value].sort((a,b)=>Number(matchingWorkMilestone(b,snapshot.value))-Number(matchingWorkMilestone(a,snapshot.value))));
watch(candidates,items=>{if(!items.some(t=>t.id===attachTarget.value))attachTarget.value=items[0]?.id||'';},{immediate:true});
async function attach(){const t=tracked.value.find(t=>t.id===attachTarget.value);if(t&&await changeTracker('attach-saved-work',t))selectedTracker.value=t.id;}
watch(()=>snapshot.value?.generatedAt,()=>{notice.value='';});
watch(()=>form.repo,()=>{milestones.value=[];form.milestone=0;milestoneText.value='';lookupError.value='';},{flush:'sync'});
watch(activeTab,async tab=>{if(tab==='my-work'){await refreshMyWork();scopeOpen.value=!snapshot.value;if(snapshot.value){Object.assign(form,snapshot.value.config);milestoneText.value=snapshot.value.milestone.title;}}}, {immediate:true});
async function lookup(){const repo=form.repo;lookupBusy.value=true;lookupError.value='';try{const response=await apiFetch('/api/issue-radar/milestones',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repo})});if(!response.ok)throw new Error(await response.text());const data=await response.json();if(repo!==form.repo)return;milestones.value=data.milestones||[];showMilestones.value=true;if(!milestones.value.length)lookupError.value='No milestones found in this repository.';return milestones.value;}catch(err){lookupError.value=err.message;}finally{lookupBusy.value=false;}}
async function pull(){if(loading.value||lookupBusy.value)return;notice.value='';lookupError.value='';if(!intakeMilestone.value){const items=await lookup();if(!items)return;}if(!intakeMilestone.value){lookupError.value=`No exact milestone matches “${milestoneText.value.trim()}”. Search the GitHub list and select a milestone.`;return;}try{const result=await pullMyWork({...form,milestone:intakeMilestone.value.number});Object.assign(form,result.config);milestoneText.value=result.milestone.title;scopeOpen.value=false;showMilestones.value=false;notice.value=`${result.created} starter ${result.created===1?'package':'packages'} created. Existing plans and package placement preserved.`;}catch{/* Shared error shown below. */}}
</script>
<template>
<div class="my-work">
 <header class="mw-hero"><div><span class="mw-eyebrow">Your working queue</span><h1>My Work<span class="mw-dot">.</span></h1><p>Your releases, next actions, and test evidence.</p></div><button class="mw-secondary" @click="setActivePanelTab('packages')"><Icon name="folder"/>Package library <Icon name="arrow"/></button></header>
 <ReleaseTrackers compact><template #tracker="{tracker}"><TrackerWorkQueue :tracker="tracker"/></template></ReleaseTrackers>
 <p v-if="error" class="mw-alert" role="alert">{{error}}</p><p v-if="notice" class="mw-notice" role="status">{{notice}}</p>
 <section v-if="unlinked" class="mw-surface"><div class="mw-section-heading"><h2>Existing My Work · {{snapshot.milestone.title}}</h2><span class="mw-caption">Not linked to a release tracker</span></div><p class="mw-caption">Keep your saved issues, plans, and evidence together in a release tracker.</p><div v-if="candidates.length" class="mw-queue-tools" style="margin:12px 0"><select v-model="attachTarget" aria-label="Tracker for existing work"><option v-for="t in candidates" :key="t.id" :value="t.id">{{t.name}}{{matchingWorkMilestone(t,snapshot)?' · matching milestone':''}}</option></select><button class="mw-primary" :disabled="trackerBusy" @click="attach">Add existing work</button></div><TrackerWorkQueue :snapshot="snapshot"/></section>
 <details class="mw-support"><summary>Individual milestone intake</summary> <details class="mw-scope-shell mw-surface" :open="scopeOpen" @toggle="scopeOpen=$event.target.open"><summary>Milestone &amp; scope <span>{{snapshot?`${snapshot.config.repo} · ${snapshot.milestone.title}`:'Choose your work'}} · {{scopeOpen?'Collapse':'Edit'}}</span></summary><form class="mw-scope" @submit.prevent="pull"><div class="mw-scope-heading"><strong>Pull your milestone</strong><span>Reads GitHub · prepares local packages</span></div><div class="mw-fields"><label>Repository<input autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" v-model="form.repo" required placeholder="owner/repo" :disabled="loading||lookupBusy"/></label><div class="mw-milestone-field"><label for="mw-milestone">Milestone<input id="mw-milestone" v-model="milestoneText" type="text" required placeholder="2.16.0 or v2.16.0" :disabled="loading||lookupBusy" autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off"/></label><button type="button" class="mw-link" :disabled="lookupBusy||loading" @click="showMilestones?showMilestones=false:lookup()">{{lookupBusy?'Loading…':showMilestones?'Hide milestones':'Choose from GitHub'}}</button><MilestoneOptions v-if="showMilestones&&milestones.length" :items="milestones" :selected="intakeMilestone?.number||0" :disabled="loading||lookupBusy" @select="milestoneText=$event.title;showMilestones=false"/></div><label>Owner scope<select v-model="form.scope" :disabled="loading"><option value="mine">Assigned to me</option><option value="unassigned">Unassigned</option><option value="all">Entire milestone</option></select></label><label v-if="form.scope==='mine'">GitHub username<input autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" v-model="form.user" placeholder="Signed-in account by default" :disabled="loading"/></label><label>Labels · optional<input autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" v-model="form.label" placeholder="team/frameworks" :disabled="loading"/></label></div><div class="mw-scope-bottom"><p>Creates a milestone bucket and starter packages for open issues. Starters need your test cases. Existing packages stay intact.</p><button class="mw-primary" :disabled="loading||lookupBusy||!milestoneText.trim()">{{loading?'Pulling & preparing…':snapshot?'Refresh & prepare':'Pull & prepare'}}<Icon name="arrow"/></button></div><p v-if="lookupError" role="alert">{{lookupError}}</p></form></details>
 <div v-if="snapshot" class="mw-refresh-row"><span role="status">{{refreshing?'Refreshing ownership, QA labels, and issue state from GitHub…':'Refreshes when you return to My Work.'}}</span><button class="mw-secondary" :disabled="refreshing||loading" @click="refreshMyWork({force:true})">{{refreshing?'Refreshing…':'Refresh issues'}}</button></div>
</details>
</div>
</template>
