font-size:15px;font-weight:600}.mw-issue-copy>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:9px}.mw-badge{font-size:10px;padding:4px 8px;border-radius:5px;background:#31947612}.mw-badge[data-closed=true]{background:#7760ba20}.mw-empty{text-align:center;padding:50px 20px;color:var(--mw-muted)}.mw-empty>svg{margin:0 auto 14px;width:32px;height:32px}.mw-empty h2,.mw-empty h3{color:var(--mw-text);margin-bottom:10px}.mw-journey{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:28px;font-size:12px}.mw-departed summary{cursor:pointer;font-weight:600}.mw-departed p{margin:12px 0}.mw-departed a{font-size:13px}.mw-departed>div{margin-top:8px}@media(max-width:1100px){.mw-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.mw-charts{grid-template-columns:1fr}.mw-stats{grid-template-columns:repeat(2,1fr)}.mw-issue{flex-wrap:wrap}.mw-issue-copy{flex-basis:70%}.mw-surface{padding:18px}.mw-queue-tools{width:100%}.mw-queue-tools input{width:100%}}

